import { midnightBundlesV2Abi } from "@morpho-org/midnight-sdk";
import {
  ChainId,
  getChainAddress,
  registerCustomAddresses,
} from "@morpho-org/morpho-ts";
import type { AnvilTestClient } from "@morpho-org/test";
import { type Address, parseEther } from "viem";
import type { base } from "viem/chains";

/**
 * Creation bytecode for MidnightBundlesV2 from `morpho-org/bundles` commit
 * `07f293b383824b35adc745454ac2622a27eb0502`, used to deploy it on pinned forks
 * until a verified deployment is registered.
 */
export const midnightBundlesV2Bytecode =
  "" as const;

/** Fresh deployer so every fork test deploys MidnightBundlesV2 at the same address. */
const deployer = "0x00000000000000000000000000000000000b2d00" as Address;

/** Deploys MidnightBundlesV2 on a Base fork and registers it as `midnightBundlesV2`. */
export const deployMidnightBundlesV2 = async (
  client: AnvilTestClient<typeof base>,
) => {
  await client.setBalance({ address: deployer, value: parseEther("1") });
  const hash = await client.deployContract({
    account: deployer,
    abi: midnightBundlesV2Abi,
    bytecode: midnightBundlesV2Bytecode,
    args: [
      getChainAddress(ChainId.BaseMainnet, "midnight"),
      getChainAddress(ChainId.BaseMainnet, "blue"),
      getChainAddress(ChainId.BaseMainnet, "midnightBlueBuyCallbackFactory"),
      getChainAddress(ChainId.BaseMainnet, "midnightMempool"),
    ],
  });
  const { contractAddress } = await client.waitForTransactionReceipt({ hash });
  if (!contractAddress) throw new Error("MidnightBundlesV2 deployment failed");
  registerCustomAddresses({
    addresses: {
      [ChainId.BaseMainnet]: { midnightBundlesV2: contractAddress },
    },
  });
  return contractAddress;
};
